            node.value = str(round(random.uniform(-5.0, 5.0), 2))
    else:
        _, arity = OPERATORS[node.value]
        same_arity = [n for n, (_, a) in OPERATORS.items() if a == arity]
        if same_arity:
            node.value = random.choice(same_arity)
    return offspring


def _hoist_mutation(parent, n_features, max_depth=17):
    """Replace tree with one of its subtrees (bloat reduction)."""
    offspring = parent.copy()
    nodes = offspring.get_all_nodes()
    if len(nodes) <= 2:
        return offspring
    idx = random.randint(1, len(nodes) - 1)
    return nodes[idx][0].copy()


def _constant_perturbation(parent, n_features, max_depth=17):
    """Perturb numeric constants via additive, multiplicative, or snap-to-int."""
    offspring = parent.copy()
    nodes = offspring.get_all_nodes()
    any_perturbed = False
    for node, _, _ in nodes:
        if node.is_terminal:
            try:
                val = float(node.value)
                if random.random() < 0.4:
                    r = random.random()
                    if r < 0.3:
                        val += random.gauss(0, 0.5)
                    elif r < 0.6:
                        val *= random.gauss(1.0, 0.2)
                    elif r < 0.8:
                        val = round(val)
                    else:
                        val = random.uniform(-3.0, 3.0)
                    node.value = str(round(val, 4))
                    any_perturbed = True
            except (ValueError, TypeError):
                pass
    if not any_perturbed:
        return _subtree_mutation(parent, n_features, max_depth)
    return offspring


