def _lexicase_selection(population, fitnesses, n_select, errors=None):
    """Epsilon-lexicase selection with semi-dynamic MAD-based epsilon
    (La Cava et al., GECCO 2016). Filters candidates on randomly ordered
    training cases, keeping only those within epsilon = MAD of the best
    on each case."""
    if errors is None:
        return _tournament_selection(population, fitnesses, n_select)

    selected = []
    pop_size = len(population)
    n_cases = errors.shape[1]

    for _ in range(n_select):
        candidates = list(range(pop_size))
        cases = list(range(n_cases))
        random.shuffle(cases)

        for case in cases:
            if len(candidates) <= 1:
                break
            case_errors = errors[candidates, case]
            min_err = float(np.min(case_errors))
            median_err = float(np.median(case_errors))
            mad = float(np.median(np.abs(case_errors - median_err)))
            epsilon = max(mad, 1e-10)
            survivors = [c for c, e in zip(candidates, case_errors)
                         if e <= min_err + epsilon]
            if survivors:
                candidates = survivors

        winner = random.choice(candidates)
        selected.append(population[winner].copy())

    return selected


