    """Hoist mutation: replace tree with one of its subtrees (reduces bloat)."""
    nodes = parent.get_all_nodes()
    if len(nodes) <= 1:
        return parent.copy()
    idx = random.randint(1, len(nodes) - 1)
    return nodes[idx][0].copy()


