                # Post-crossover: point mutation with small probability
                if random.random() < 0.1:
                    child = _point_mutation(child, n_features)
                # Constant perturbation for fine-tuning
                if random.random() < 0.15:
                    child = _perturb_constants(child, noise_scale=0.1)
            else:
                parents = selection(population, penalized, 1, _errors=errors)
                child = mutation(parents[0], n_features, max_depth)
            candidates.append(child)

        # Evaluate both candidates and keep the better one
        cand_fits = []
        for c in candidates:
            try:
                cand_fits.append(fitness_function(c, X_train, y_train))
            except Exception:
                cand_fits.append(float('inf'))

        best_c = candidates[0] if cand_fits[0] <= cand_fits[1] else candidates[1]
        new_population.append(best_c)

    # Inject fresh random individuals for diversity maintenance
    for _ in range(n_inject):
        depth = random.randint(2, min(4, max_depth))
        new_population.append(generate_tree('grow', depth, n_features))

    return new_population[:pop_size]

