def _tournament(population, fitnesses, n, k=7):
    """Tournament selection with configurable tournament size."""
    selected = []
    ps = len(population)
    for _ in range(n):
        cands = random.sample(range(ps), min(k, ps))
        best = min(cands, key=lambda i: fitnesses[i])
        selected.append(population[best].copy())
    return selected


def _lexicase(population, errors, n):
    """Epsilon-lexicase selection (La Cava 2016).
    Semi-dynamic epsilon based on MAD of candidate errors per case."""
    selected = []
    ps = len(population)
    nc = errors.shape[1]
    for _ in range(n):
        cands = list(range(ps))
        cases = list(range(nc))
        random.shuffle(cases)
        for case in cases:
            if len(cands) <= 1:
                break
            ce = errors[cands, case]
            mn = float(np.min(ce))
            med = float(np.median(ce))
            mad = float(np.median(np.abs(ce - med)))
            eps = max(mad, 1e-10)
            cands = [c for c, e in zip(cands, ce) if e <= mn + eps]
        selected.append(population[random.choice(cands)].copy())
    return selected


def selection(population, fitnesses, n_select, **kwargs):
