def crossover(parent1, parent2, n_features, max_depth=17):
    """Subtree crossover with 90% function-node bias for meaningful recombination.
    Selecting function nodes (vs terminals) ensures crossover swaps substantive
    sub-expressions rather than trivial leaf replacements."""
    off = parent1.copy()
    don = parent2.copy()
    off_n = off.get_all_nodes()
    don_n = don.get_all_nodes()
    if len(off_n) <= 1 or len(don_n) <= 1:
        return off

    # Function-node biased crossover points
    f_off = [i for i, (nd, _, _) in enumerate(off_n) if not nd.is_terminal]
    f_don = [i for i, (nd, _, _) in enumerate(don_n) if not nd.is_terminal]

    if f_off and random.random() < 0.9:
        op = random.choice(f_off)
    else:
        op = random.randint(1, len(off_n) - 1)

    if f_don and random.random() < 0.9:
        dp = random.choice(f_don)
    else:
        dp = random.randint(0, len(don_n) - 1)

    sub = don_n[dp][0].copy()
    node, par, ci = off_n[op]
    if par is not None:
        par.children[ci] = sub
    else:
        off = sub

    if off.depth() > max_depth:
        return parent1.copy()
    return off


def _sub_mut(parent, n_features, max_depth):
