def _pt_mut(parent, n_features, max_depth):
    """Point mutation: change a single node's value.
    For terminals: switch variable/constant or perturb constant (Gaussian).
    For operators: swap to another operator with same arity.
    Critical for constant fine-tuning in symbolic regression."""
    off = parent.copy()
    nodes = off.get_all_nodes()
    if not nodes:
        return off
    idx = random.randint(0, len(nodes) - 1)
    node, par, ci = nodes[idx]
    if node.is_terminal:
        r = random.random()
        if r < 0.3:
            node.value = f'x{random.randint(0, n_features - 1)}'
        elif r < 0.6:
            node.value = str(round(random.uniform(-5.0, 5.0), 2))
        else:
