        same = [op for op in OPERATOR_NAMES if OPERATORS[op][1] == arity and op != node.value]
        if same:
            node.value = random.choice(same)
    return off


def _shrink_mut(parent, n_features, max_depth):
    """Shrink/hoist mutation: replace subtree with one of its terminals.
    Effective bloat reduction operator that simplifies expressions."""
    off = parent.copy()
    nodes = off.get_all_nodes()
    cands = []
    for i, (nd, _, _) in enumerate(nodes):
        if not nd.is_terminal:
            terms = [c for c in nd.children if c.is_terminal]
            if terms:
                cands.append((i, terms))
    if not cands:
        return _sub_mut(parent, n_features, max_depth)
    idx, terms = random.choice(cands)
    node, par, ci = nodes[idx]
    rep = random.choice(terms).copy()
    if par is not None:
        par.children[ci] = rep
    else:
        off = rep
    return off


def mutation(parent, n_features, max_depth=17):
