def _improve_constants(tree, X, y):
    """Memetic local search: greedily improve numerical constants.

    For each iteration, picks a random constant and tries deterministic
    perturbations. Keeps the best modification. This is the key mechanism
    for fine-tuning coefficients like the '2' in 2*sin(x)*cos(y).
    """
    best = tree.copy()
    best_f = float(np.mean((y - safe_evaluate(best, X)) ** 2))
    for _ in range(5):
        c = best.copy()
        cns = [n for n, _, _ in c.get_all_nodes()
               if n.is_terminal and not (isinstance(n.value, str) and n.value.startswith('x'))]
        if not cns:
            break
        nd = random.choice(cns)
        old = float(nd.value)
        trials = [old * 1.1, old * 0.9, old + 0.5, old - 0.5,
                  old + 0.1, old - 0.1, old * 2.0, old * 0.5,
                  old + random.gauss(0, 0.5), random.gauss(0, 1.0)]
        for t in trials:
            nd.value = str(round(t, 4))
            f = float(np.mean((y - safe_evaluate(c, X)) ** 2))
            if f < best_f:
                best_f = f
                best = c.copy()
        nd.value = str(round(old, 4))
    return best


