def selection(population, fitnesses, n_select, tournament_size=7, _errors=None):
    """Discriminative epsilon-lexicase selection.

    Novel contribution: fitness cases are ordered with probability
    proportional to their *discriminative power* (inter-individual error
    variance across the current population).  Cases where individuals
    disagree most are presented first in the lexicase filter, so that
    the most informative comparisons drive parent selection.  Mixed
    with uniform random ordering (30 %) for robustness.
    Falls back to tournament selection when per-case errors unavailable.
    """
    selected = []
    pop_size = len(population)

    if _errors is None:
        for _ in range(n_select):
            candidates = random.sample(range(pop_size), min(tournament_size, pop_size))
            best = min(candidates, key=lambda i: fitnesses[i])
            selected.append(population[best].copy())
        return selected

    n_cases = _errors.shape[1]

    # Discriminative weights: variance of error across individuals per case
    case_var = np.var(_errors, axis=0)
    total_v = float(case_var.sum())
    if total_v > 1e-15:
        cp = case_var / total_v
        cp = cp / cp.sum()  # renormalise for float safety
        case_probs = cp.tolist()
    else:
        case_probs = None

    for _ in range(n_select):
        candidates = list(range(pop_size))

        # 70 % discriminative ordering, 30 % random
        use_weighted = case_probs is not None and random.random() < 0.7
        if use_weighted:
            try:
                cases = list(np.random.choice(
                    n_cases, size=n_cases, replace=False, p=case_probs))
            except (ValueError, FloatingPointError):
                cases = list(range(n_cases))
                random.shuffle(cases)
        else:
            cases = list(range(n_cases))
            random.shuffle(cases)

        for case in cases:
            if len(candidates) <= 1:
                break
            case_errors = _errors[candidates, case]
            min_err = float(np.min(case_errors))
            mad = float(np.median(np.abs(
                case_errors - float(np.median(case_errors)))))
            eps = max(mad, 1e-10)
            candidates = [c for c, e in zip(candidates, case_errors)
                          if e <= min_err + eps]

        winner = random.choice(candidates)
        selected.append(population[winner].copy())

    return selected


